// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

library CyberValley {
    struct Multihash {
        bytes32 digest;
        uint8 hashFunction;
        uint8 size;
    }
}

contracts/CyberValleyEventManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./CyberValleyEventTicket.sol";
import "./DateOverlapChecker.sol";
import "./CyberValley.sol";
import "./IDynamicRevenueSplitter.sol";
import "./IReferralRewards.sol";

// TODO: Pad layout after general work finish
contract CyberValleyEventManager is AccessControl, DateOverlapChecker {
    using CyberValley for CyberValley.Multihash;

    bytes32 public constant MASTER_ROLE = keccak256("MASTER_ROLE");
    bytes32 public constant LOCAL_PROVIDER_ROLE = keccak256("LOCAL_PROVIDER_ROLE");
    bytes32 public constant VERIFIED_SHAMAN_ROLE = keccak256("VERIFIED_SHAMAN_ROLE");
    bytes32 public constant BACKEND_ROLE = keccak256("BACKEND_ROLE");

    // LOCAL_PROVIDER_ROLE is the primary "event manager" role; MASTER_ROLE should be
    // able to act across all providers for operational recovery (e.g. close/cancel).
    modifier onlyLocalProviderOrMaster() {
        if (!hasRole(MASTER_ROLE, msg.sender)) {
            _checkRole(LOCAL_PROVIDER_ROLE);
        }
        _;
    }

    enum EventPlaceStatus {
        Submitted,
        Approved,
        Declined
    }

    struct EventPlace {
        address requester;
        address provider;
        uint16 maxTickets;
        uint16 minTickets;
        uint256 minPrice;
        uint8 daysBeforeCancel;
        uint8 minDays;
        bool available;
        EventPlaceStatus status;
        CyberValley.Multihash meta;
        uint256 eventDepositSize;
    }

    enum EventStatus {
        Submitted,
        Approved,
        Declined,
        Cancelled,
        Closed
    }

    // TODO: Add IPFS multihash
    struct TicketCategory {
        string name;
        uint256 eventId;
        uint16 discountPercentage;
        uint16 quota;
        bool hasQuota;
        uint16 sold;
    }

    // Input struct for creating categories during event submission
    struct CategoryInput {
        string name;
        uint16 discountPercentage;
        uint16 quota;
        bool hasQuota;
    }

    struct Event {
        address creator;
        uint256 eventPlaceId;
        uint256 ticketPrice;
        uint256 startDate;
        uint16 daysAmount;
        EventStatus status;
        address[] customers;
        CyberValley.Multihash meta;
        uint256 networth;
        uint256 totalCategoryQuota; // Gas-efficient tracking of category quotas
    }

    event NewEventPlaceRequest(
        uint256 id,
        address requester,
        uint16 maxTickets,
        uint16 minTickets,
        uint256 minPrice,
        uint8 daysBeforeCancel,
        uint8 minDays,
        bool available,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size
    );
    event EventPlaceUpdated(
        address provider,
        uint256 eventPlaceId,
        uint16 maxTickets,
        uint16 minTickets,
        uint256 minPrice,
        uint8 daysBeforeCancel,
        uint8 minDays,
        bool available,
        EventPlaceStatus status,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        uint256 eventDepositSize
    );
    event NewEventRequest(
        uint256 id,
        address creator,
        uint256 eventPlaceId,
        uint256 ticketPrice,
        uint256 startDate,
        uint16 daysAmount,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size
    );
    event EventStatusChanged(uint256 eventId, EventStatus status);
    event EventUpdated(
        uint256 id,
        uint256 eventPlaceId,
        uint256 ticketPrice,
        uint256 startDate,
        uint16 daysAmount,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size
    );
    event EventTicketVerified(uint256 tokenId);

    event TicketCategoryCreated(
        uint256 categoryId,
        uint256 indexed eventId,
        string name,
        uint16 discountPercentage,
        uint16 quota,
        bool hasQuota
    );
    event TicketCategoryUpdated(
        uint256 categoryId,
        uint256 indexed eventId,
        string name,
        uint16 discountPercentage,
        uint16 quota,
        bool hasQuota
    );
    event ReferralRewardsUpdated(address referralRewards);

    IERC20 public usdtTokenContract;
    CyberValleyEventTicket public eventTicketContract;

    address public master;
    address public revenueSplitter;
    IReferralRewards public referralRewards;

    EventPlace[] public eventPlaces;
    Event[] public events;
    TicketCategory[] public categories;
    mapping(uint256 => uint256[]) public categoryCounters;
    // NOTE: `ticketPrices` was removed because it was written but never read anywhere.

    modifier onlyExistingEvent(uint256 eventId) {
        require(eventId < events.length, "Event with given id does not exist");
        _;
    }

    /**
     * @notice Check if a place has any active events (submitted or approved status)
     * @param eventPlaceId The ID of the event place
     * @return true if there are active events at this place
     */
    function _hasActiveEvents(uint256 eventPlaceId) internal view returns (bool) {
        for (uint256 i = 0; i < events.length; i++) {
            if (events[i].eventPlaceId == eventPlaceId) {
                if (events[i].status == EventStatus.Submitted || events[i].status == EventStatus.Approved) {
                    return true;
                }
            }
        }
        return false;
    }

    constructor(
        address _usdtTokenContract,
        address _eventTicketContract,
        address _master,
        uint256 _initialOffest
    ) DateOverlapChecker(_initialOffest) {
        usdtTokenContract = IERC20(_usdtTokenContract);
        eventTicketContract = CyberValleyEventTicket(_eventTicketContract);
        master = _master;

        _grantRole(DEFAULT_ADMIN_ROLE, _master);
        _grantRole(MASTER_ROLE, _master);
        _grantRole(LOCAL_PROVIDER_ROLE, _master);
        _setRoleAdmin(VERIFIED_SHAMAN_ROLE, BACKEND_ROLE);
    }

    function setReferralRewards(address _referralRewards) external onlyRole(MASTER_ROLE) {
        referralRewards = IReferralRewards(_referralRewards);
        emit ReferralRewardsUpdated(_referralRewards);
    }

    /**
     * @notice Grants local provider role and sets their bps share in RevenueSplitter
     * @param eoa The address to grant LOCAL_PROVIDER_ROLE to
     * @param bps The basis points (0-8500) this provider receives from each distribution.
     *           Applied after fixed bps (CyberiaDAO 10% + CVE PT PMA 5%) and before 
     *           profile recipients. Provider cannot add themselves to distribution profiles.
     */
    function grantLocalProvider(address eoa, uint256 bps) external onlyRole(MASTER_ROLE) {
        require(eoa != address(0), "Local provider cannot be zero address");
        require(revenueSplitter != address(0), "Revenue splitter not set");
        _grantRole(LOCAL_PROVIDER_ROLE, eoa);
        // Bps validation happens in RevenueSplitter. Provider gets bps automatically
        // and cannot add themselves to distribution profiles.
        IDynamicRevenueSplitter(revenueSplitter).grantProfileManager(eoa, bps);
    }

    function revokeLocalProvider(address eoa) external onlyRole(MASTER_ROLE) {
        // Transfer all EventPlaces owned by the LocalProvider to Master
        for (uint256 i = 0; i < eventPlaces.length; i++) {
            if (eventPlaces[i].provider == eoa) {
                eventPlaces[i].provider = master;

                // Emit EventPlaceUpdated event for the transfer
                emit EventPlaceUpdated(
                    master,
                    i,
                    eventPlaces[i].maxTickets,
                    eventPlaces[i].minTickets,
                    eventPlaces[i].minPrice,
                    eventPlaces[i].daysBeforeCancel,
                    eventPlaces[i].minDays,
                    eventPlaces[i].available,
                    eventPlaces[i].status,
                    eventPlaces[i].meta.digest,
                    eventPlaces[i].meta.hashFunction,
                    eventPlaces[i].meta.size,
                    eventPlaces[i].eventDepositSize
                );
            }
        }

        // Transfer all profile ownership from revoked provider to master
        IDynamicRevenueSplitter(revenueSplitter).transferAllProfiles(eoa, master);

        _revokeRole(LOCAL_PROVIDER_ROLE, eoa);
    }

    function revokeVerifiedShaman(address eoa) external onlyRole(LOCAL_PROVIDER_ROLE) {
        _revokeRole(VERIFIED_SHAMAN_ROLE, eoa);
    }

    function setRevenueSplitter(address _splitter) external onlyRole(MASTER_ROLE) {
        require(_splitter != address(0), "Splitter address cannot be zero");
        revenueSplitter = _splitter;
    }

    function submitEventPlaceRequest(
        uint16 _maxTickets,
        uint16 _minTickets,
        uint256 _minPrice,
        uint8 _daysBeforeCancel,
        uint8 _minDays,
        bool _available,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        uint256 _eventDepositSize
    ) external {
        bool isLocalProvider = hasRole(LOCAL_PROVIDER_ROLE, msg.sender);
	require(isLocalProvider || hasRole(VERIFIED_SHAMAN_ROLE, msg.sender), "access denied");

        // If local provider is creating, deposit must be > 0
        // If shaman is requesting, deposit can be 0 (will be set during approval)
        if (isLocalProvider) {
            require(_eventDepositSize > 0, "Deposit must be greater than zero");
        }

        eventPlaces.push(EventPlace({
            requester: msg.sender,
            provider: isLocalProvider ? msg.sender : address(0),
            maxTickets: _maxTickets,
            minTickets: _minTickets,
            minPrice: _minPrice,
            daysBeforeCancel: _daysBeforeCancel,
            minDays: _minDays,
            available: _available,
            status: isLocalProvider ? EventPlaceStatus.Approved : EventPlaceStatus.Submitted,
            meta: CyberValley.Multihash({
                digest: digest,
                hashFunction: hashFunction,
                size: size
            }),
            eventDepositSize: _eventDepositSize
        }));

        uint256 eventPlaceId = eventPlaces.length - 1;
        _validateEventPlace(eventPlaces[eventPlaceId]);

        if (isLocalProvider) {
            emit EventPlaceUpdated(
                msg.sender,
                eventPlaceId,
                _maxTickets,
                _minTickets,
                _minPrice,
                _daysBeforeCancel,
                _minDays,
                _available,
                EventPlaceStatus.Approved,
                digest,
                hashFunction,
                size,
                _eventDepositSize
            );
        } else {
            emit NewEventPlaceRequest(
                eventPlaceId,
                msg.sender,
                _maxTickets,
                _minTickets,
                _minPrice,
                _daysBeforeCancel,
                _minDays,
                _available,
                digest,
                hashFunction,
                size
            );
        }
    }

    function approveEventPlace(
        uint256 eventPlaceId,
        uint256 _eventDepositSize
    ) external onlyRole(LOCAL_PROVIDER_ROLE) {
        require(eventPlaceId < eventPlaces.length, "EventPlace does not exist");
        require(_eventDepositSize > 0, "Deposit must be greater than zero");
        EventPlace storage place = eventPlaces[eventPlaceId];
        require(
            place.status == EventPlaceStatus.Submitted,
            "EventPlace status differs from submitted"
        );
        place.status = EventPlaceStatus.Approved;
        place.provider = msg.sender;
        place.eventDepositSize = _eventDepositSize;
        emit EventPlaceUpdated(
            msg.sender,
            eventPlaceId,
            place.maxTickets,
            place.minTickets,
            place.minPrice,
            place.daysBeforeCancel,
            place.minDays,
            place.available,
            place.status,
            place.meta.digest,
            place.meta.hashFunction,
            place.meta.size,
            place.eventDepositSize
        );
    }

    function declineEventPlace(
        uint256 eventPlaceId
    ) external onlyRole(LOCAL_PROVIDER_ROLE) {
        require(eventPlaceId < eventPlaces.length, "EventPlace does not exist");
        EventPlace storage place = eventPlaces[eventPlaceId];
        require(
            place.status == EventPlaceStatus.Submitted,
            "EventPlace status differs from submitted"
        );
        place.status = EventPlaceStatus.Declined;
        // No event emitted for declined places
    }

    function updateEventPlace(
        uint256 eventPlaceId,
        uint16 _maxTickets,
        uint16 _minTickets,
        uint256 _minPrice,
        uint8 _daysBeforeCancel,
        uint8 _minDays,
        bool _available,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        uint256 _eventDepositSize
    ) external onlyRole(LOCAL_PROVIDER_ROLE) {
        require(eventPlaceId < eventPlaces.length, "eventPlaceId should exist");
        EventPlace storage place = eventPlaces[eventPlaceId];
        require(
            place.provider == msg.sender,
            "Given event place belongs to another provider"
        );
        require(
            place.status == EventPlaceStatus.Approved,
            "EventPlace must be approved to be updated"
        );

        // Only allow deposit change if there are no active events
        if (_eventDepositSize != place.eventDepositSize) {
            require(
                !_hasActiveEvents(eventPlaceId),
                "Cannot change deposit while there are active events"
            );
            require(_eventDepositSize > 0, "Deposit must be greater than zero");
            place.eventDepositSize = _eventDepositSize;
        }

        place.maxTickets = _maxTickets;
        place.minTickets = _minTickets;
        place.minPrice = _minPrice;
        place.daysBeforeCancel = _daysBeforeCancel;
        place.minDays = _minDays;
        place.available = _available;
        place.meta = CyberValley.Multihash({
            digest: digest,
            hashFunction: hashFunction,
            size: size
        });

        _validateEventPlace(place);
        emit EventPlaceUpdated(
            msg.sender,
            eventPlaceId,
            _maxTickets,
            _minTickets,
            _minPrice,
            _daysBeforeCancel,
            _minDays,
            _available,
            place.status,
            digest,
            hashFunction,
            size,
            place.eventDepositSize
        );
    }

    function _validateEventPlace(EventPlace memory eventPlace) internal pure {
        require(
            eventPlace.maxTickets >= eventPlace.minTickets,
            "Max tickets must be greater or equal min tickets"
        );
        require(
            eventPlace.maxTickets > 0 &&
                eventPlace.minTickets > 0 &&
                eventPlace.minPrice > 0 &&
                eventPlace.daysBeforeCancel > 0 &&
                eventPlace.minDays > 0,
            "Values must be greater than zero"
        );
    }

    function submitEventRequest(
        uint256 eventPlaceId,
        uint256 ticketPrice,
        uint256 startDate,
        uint16 daysAmount,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        CategoryInput[] calldata categoriesInput
    ) external {
        require(eventPlaceId < eventPlaces.length, "EventPlace does not exist");
        EventPlace storage place = eventPlaces[eventPlaceId];
        require(
            place.eventDepositSize > 0,
            "EventPlace deposit must be set"
        );
        require(
            usdtTokenContract.balanceOf(msg.sender) >= place.eventDepositSize,
            "Not enough tokens"
        );
        require(
            usdtTokenContract.allowance(msg.sender, address(this)) >=
                place.eventDepositSize,
            "Required amount was not allowed"
        );
        require(
            usdtTokenContract.transferFrom(
                msg.sender,
                address(this),
                place.eventDepositSize
            ),
            "Event request payment failed"
        );
        events.push(
            Event({
                creator: msg.sender,
                eventPlaceId: eventPlaceId,
                ticketPrice: ticketPrice,
                startDate: floorTimestampToDate(startDate),
                daysAmount: daysAmount,
                status: EventStatus.Submitted,
                customers: new address[](0),
                meta: CyberValley.Multihash({
                    digest: digest,
                    hashFunction: hashFunction,
                    size: size
                }),
                networth: 0,
                totalCategoryQuota: 0
            })
        );
        uint256 eventId = events.length - 1;
        validateEvent(events[eventId]);

        // Create categories atomically with the event
        require(categoriesInput.length > 0, "At least one category is required");
        for (uint256 i = 0; i < categoriesInput.length; i++) {
            CategoryInput memory cat = categoriesInput[i];
            _createCategoryForEvent(
                eventId,
                cat.name,
                cat.discountPercentage,
                cat.quota,
                cat.hasQuota
            );
        }

        // Validate that categories are within boundaries
        Event storage newEvent = events[eventId];
        EventPlace storage eventPlace = eventPlaces[newEvent.eventPlaceId];
        bool hasUnlimited = _eventHasUnlimitedCategory(eventId);
        if (!hasUnlimited) {
            require(
                newEvent.totalCategoryQuota >= eventPlace.minTickets,
                "Total tickets must be at least minTickets"
            );
            require(
                newEvent.totalCategoryQuota <= eventPlace.maxTickets,
                "Total tickets cannot exceed maxTickets"
            );
        }

        emit NewEventRequest(
            eventId,
            msg.sender,
            eventPlaceId,
            ticketPrice,
            startDate,
            daysAmount,
            digest,
            hashFunction,
            size
        );
    }

    function approveEvent(
        uint256 eventId,
        uint256 distributionProfileId
    ) external onlyLocalProviderOrMaster onlyExistingEvent(eventId) {
        Event storage evt = events[eventId];
        ensureEventBelongsToProviderOrMaster(evt.eventPlaceId);
        require(
            evt.status == EventStatus.Submitted,
            "Event status differs from submitted"
        );
        require(
            categoryCounters[eventId].length > 0,
            "Event must have at least one category"
        );

        // Validate profile ownership - caller must own the profile
        require(
            IDynamicRevenueSplitter(revenueSplitter).isProfileOwner(
                distributionProfileId,
                msg.sender
            ),
            "Caller must own the distribution profile"
        );

        // Set event profile in revenue splitter
        IDynamicRevenueSplitter(revenueSplitter).setEventProfile(
            eventId,
            distributionProfileId
        );

        allocateDateRange(
            evt.eventPlaceId,
            evt.startDate,
            calcDaysAfter(evt.startDate, evt.daysAmount)
        );
        evt.status = EventStatus.Approved;
        emit EventStatusChanged(eventId, evt.status);
    }

    function declineEvent(
        uint256 eventId
    ) external onlyLocalProviderOrMaster onlyExistingEvent(eventId) {
        Event storage evt = events[eventId];
        ensureEventBelongsToProviderOrMaster(evt.eventPlaceId);
        require(
            evt.status == EventStatus.Submitted,
            "Event status differs from submitted"
        );
        EventPlace storage place = eventPlaces[evt.eventPlaceId];
        require(
            usdtTokenContract.transfer(evt.creator, place.eventDepositSize),
            "Failed to refund event request"
        );
        evt.status = EventStatus.Declined;
        freeDateRange(
            evt.eventPlaceId,
            evt.startDate,
            calcDaysAfter(evt.startDate, evt.daysAmount)
        );
        emit EventStatusChanged(eventId, evt.status);
    }

    function updateEvent(
        uint256 eventId,
        uint256 eventPlaceId,
        uint256 ticketPrice,
        uint256 startDate,
        uint16 daysAmount,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size
    ) external onlyRole(LOCAL_PROVIDER_ROLE) onlyExistingEvent(eventId) {
        Event storage evt = events[eventId];
        ensureEventBelongsToProvider(evt.eventPlaceId);

        // Capture old values BEFORE any mutations
        uint256 oldEventPlaceId = evt.eventPlaceId;
        uint256 oldStartDate = evt.startDate;
        uint256 oldDaysAmount = evt.daysAmount;

        bool realloc = oldEventPlaceId != eventPlaceId ||
            oldStartDate != startDate ||
            oldDaysAmount != daysAmount;

        evt.eventPlaceId = eventPlaceId;
        evt.ticketPrice = ticketPrice;
        evt.startDate = floorTimestampToDate(startDate);
        evt.daysAmount = daysAmount;
        evt.meta = CyberValley.Multihash({
            digest: digest,
            hashFunction: hashFunction,
            size: size
        });
        validateEvent(evt);
        if (realloc) {
            // Free the OLD date range from the OLD place
            freeDateRange(
                oldEventPlaceId,
                oldStartDate,
                calcDaysAfter(oldStartDate, oldDaysAmount)
            );
            // Allocate the NEW date range to the NEW place
            allocateDateRange(
                eventPlaceId,
                evt.startDate,
                calcDaysAfter(evt.startDate, evt.daysAmount)
            );
        }
        emit EventUpdated(
            eventId,
            eventPlaceId,
            ticketPrice,
            startDate,
            daysAmount,
            digest,
            hashFunction,
            size
        );
    }

    function validateEvent(Event storage evt) internal view {
        EventPlace storage place = eventPlaces[evt.eventPlaceId];
        require(evt.status <= EventStatus.Approved, "Event is not available");
        require(
            place.status == EventPlaceStatus.Approved,
            "EventPlace must be approved"
        );
        require(
            place.available,
            "EventPlace is not available"
        );
        require(
            place.minPrice <= evt.ticketPrice,
            "Ticket price is less than allowed"
        );
        require(
            place.minDays <= evt.daysAmount,
            "Days amount is less than allowed"
        );
        require(
            floorTimestampToDate(block.timestamp) +
                SECONDS_IN_DAY *
                (place.daysBeforeCancel) <=
                evt.startDate,
            "Not enough time to avoid cancelling"
        );
        // Saves from requests that will allocate a lot of buckets
        // in the `DateOverlapChecker`
        // Written when BUCKET_SIZE == 256
        require(
            evt.startDate - floorTimestampToDate(block.timestamp) <=
                SECONDS_IN_DAY * BUCKET_SIZE,
            "Requested event is too far in the future"
        );
        require(
            checkNoOverlap(
                evt.eventPlaceId,
                evt.startDate,
                calcDaysAfter(evt.startDate, evt.daysAmount)
            ),
            "Requested event overlaps with existing"
        );
    }

    function mintTicket(
        uint256 eventId,
        uint256 categoryId,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        address referrer
    ) external onlyExistingEvent(eventId) {
        _mintTicketInternal(eventId, categoryId, 1, digest, hashFunction, size, referrer);
    }

    function mintTickets(
        uint256 eventId,
        uint256 categoryId,
        uint256 amount,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        address referrer
    ) external onlyExistingEvent(eventId) {
        _mintTicketInternal(eventId, categoryId, amount, digest, hashFunction, size, referrer);
    }

    function _mintTicketInternal(
        uint256 eventId,
        uint256 categoryId,
        uint256 amount,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        address referrer
    ) internal onlyExistingEvent(eventId) {
        require(amount > 0, "Amount must be greater than 0");

        Event storage evt = events[eventId];
        require(evt.status == EventStatus.Approved, "Event is not approved");

        // Category is required
        require(categoryId < categories.length, "Category does not exist");
        TicketCategory storage category = categories[categoryId];
        require(category.eventId == eventId, "Category does not belong to this event");

        if (category.hasQuota) {
            require(category.sold + uint16(amount) <= category.quota, "Category quota exceeded");
            category.sold += uint16(amount);
        }
        uint256 unitPrice = applyDiscount(evt.ticketPrice, category.discountPercentage);
        uint256 totalPrice = unitPrice * amount;

        require(
            usdtTokenContract.transferFrom(
                msg.sender,
                address(this),
                totalPrice
            ),
            "Failed to transfer tokens"
        );

        // Referral payouts are taken out of event revenue (reduces `evt.networth`).
        uint256 referralPaid = 0;
        if (address(referralRewards) != address(0)) {
            address safeReferrer = referrer == msg.sender ? address(0) : referrer;

            (address[3] memory recipients, uint256[3] memory bonuses, uint256 paid) =
                referralRewards.processPurchase(msg.sender, safeReferrer, totalPrice);
            referralPaid = paid;

            for (uint256 i = 0; i < 3; i++) {
                if (recipients[i] != address(0) && bonuses[i] > 0) {
                    require(
                        usdtTokenContract.transfer(recipients[i], bonuses[i]),
                        "Failed to pay referral"
                    );
                }
            }
        }

        eventTicketContract.mintBatch(
            msg.sender,
            eventId,
            categoryId,
            amount,
            digest,
            hashFunction,
            size,
            referrer,
            // `pricePaid` is per-ticket. The indexer uses this to aggregate revenue.
            unitPrice
        );
        evt.customers.push(msg.sender);
        evt.networth += (totalPrice - referralPaid);
    }

    function applyDiscount(uint256 originalPrice, uint16 discountPercentage) internal pure returns (uint256) {
        if (discountPercentage == 0) {
            return originalPrice;
        }
        uint256 discount = (originalPrice * uint256(discountPercentage)) / 10000;
        return originalPrice - discount;
    }

    function closeEvent(
        uint256 eventId
    ) external onlyLocalProviderOrMaster onlyExistingEvent(eventId) {
        Event storage evt = events[eventId];
        ensureEventBelongsToProviderOrMaster(evt.eventPlaceId);
        require(
            evt.status == EventStatus.Approved,
            "Only event in approved state can be closed"
        );
        uint256 eventEndDate = calcDaysAfter(evt.startDate, evt.daysAmount);
        require(
            block.timestamp > eventEndDate,
            "Event has not been finished yet"
        );
        EventPlace storage place = eventPlaces[evt.eventPlaceId];
        // Return deposit to creator
        require(
            usdtTokenContract.transfer(evt.creator, place.eventDepositSize),
            "Failed to return deposit to creator"
        );
        // Distribute ticket revenue only if there is revenue
        if (evt.networth > 0) {
            distributeEventFunds(eventId, evt.networth);
        }
        evt.status = EventStatus.Closed;
        emit EventStatusChanged(eventId, evt.status);
    }

    function cancelEvent(
        uint256 eventId
    ) external onlyLocalProviderOrMaster onlyExistingEvent(eventId) {
        Event storage evt = events[eventId];
        ensureEventBelongsToProviderOrMaster(evt.eventPlaceId);
        require(
            evt.status == EventStatus.Approved,
            "Only event in approved state can be cancelled"
        );

        EventPlace storage place = eventPlaces[evt.eventPlaceId];

        // Deposit goes to shaman (event creator)
        if (place.eventDepositSize > 0) {
            require(
                usdtTokenContract.transfer(evt.creator, place.eventDepositSize),
                "Failed to refund deposit to creator"
            );
        }

        // Ticket revenue goes to local provider
        if (evt.networth > 0) {
            require(
                usdtTokenContract.transfer(place.provider, evt.networth),
                "Failed to transfer ticket revenue to provider"
            );
        }

        evt.networth = 0;
        evt.status = EventStatus.Cancelled;
        emit EventStatusChanged(eventId, evt.status);
    }

    // TODO: Publish event with funds distribution
    function distributeEventFunds(
        uint256 eventId,
        uint256 totalAmount
    ) internal {
        require(revenueSplitter != address(0), "Revenue splitter not set");
        usdtTokenContract.approve(revenueSplitter, totalAmount);
        IDynamicRevenueSplitter(revenueSplitter).distributeRevenue(totalAmount, eventId);
    }

    function floorTimestampToDate(
        uint256 timestamp
    ) internal pure returns (uint256) {
        return (timestamp / SECONDS_IN_DAY) * SECONDS_IN_DAY;
    }

    function calcDaysAfter(
        uint256 date,
        uint256 daysAmount
    ) internal pure returns (uint256) {
        return date + (daysAmount - 1) * SECONDS_IN_DAY;
    }

    function calcDaysBefore(
        uint256 date,
        uint256 daysAmount
    ) internal pure returns (uint256) {
        return date - (daysAmount - 1) * SECONDS_IN_DAY;
    }

    function _eventHasUnlimitedCategory(uint256 eventId) internal view returns (bool) {
        uint256[] storage eventCategories = categoryCounters[eventId];
        for (uint256 i = 0; i < eventCategories.length; i++) {
            if (!categories[eventCategories[i]].hasQuota) {
                return true;
            }
        }
        return false;
    }

    function ensureEventBelongsToProvider(uint256 eventPlaceId) internal view {
        require(
            eventPlaces[eventPlaceId].provider == msg.sender,
           "Given event belongs to another provider"
        );
    }

    function ensureEventBelongsToProviderOrMaster(uint256 eventPlaceId) internal view {
        if (hasRole(MASTER_ROLE, msg.sender)) {
            return;
        }
        ensureEventBelongsToProvider(eventPlaceId);
    }

    // Internal helper to create a category for an event
    function _createCategoryForEvent(
        uint256 eventId,
        string memory name,
        uint16 discountPercentage,
        uint16 quota,
        bool hasQuota
    ) internal {
        Event storage evt = events[eventId];
        require(evt.status == EventStatus.Submitted, "Event must be in submitted state");
        require(discountPercentage <= 10000, "Discount too high");

        // Gas-efficient quota validation using stored totalCategoryQuota
        if (hasQuota) {
            require(quota > 0, "Quota must be greater than 0");
            EventPlace storage place = eventPlaces[evt.eventPlaceId];
            require(quota <= place.maxTickets, "Quota exceeds event capacity");
            require(evt.totalCategoryQuota + quota <= place.maxTickets,
                "Total category quotas exceed event capacity");
            // Update stored total
            evt.totalCategoryQuota += quota;
        } else {
            require(
                !_eventHasUnlimitedCategory(eventId),
                "Only one unlimited quota category allowed"
            );
        }

        categories.push(TicketCategory({
            name: name,
            eventId: eventId,
            discountPercentage: discountPercentage,
            quota: quota,
            hasQuota: hasQuota,
            sold: 0
        }));

        uint256 categoryId = categories.length - 1;
        categoryCounters[eventId].push(categoryId);

        emit TicketCategoryCreated(
            categoryId,
            eventId,
            name,
            discountPercentage,
            quota,
            hasQuota
        );
    }

    function createCategory(
        uint256 eventId,
        string memory name,
        uint16 discountPercentage,
        uint16 quota,
        bool hasQuota
    ) external onlyRole(VERIFIED_SHAMAN_ROLE) {
        require(eventId < events.length, "Event does not exist");
        Event storage evt = events[eventId];
        // Only event creator can add categories (or local provider for any event)
        require(
            evt.creator == msg.sender || hasRole(LOCAL_PROVIDER_ROLE, msg.sender),
            "Only event creator or local provider can add categories"
        );
        _createCategoryForEvent(eventId, name, discountPercentage, quota, hasQuota);
    }

    function updateCategory(
        uint256 categoryId,
        string memory name,
        uint16 discountPercentage,
        uint16 quota,
        bool hasQuota
    ) external onlyRole(LOCAL_PROVIDER_ROLE) {
        require(categoryId < categories.length, "Category does not exist");
        require(discountPercentage <= 10000, "Discount too high");
        TicketCategory storage category = categories[categoryId];

        Event storage evt = events[category.eventId];
        EventPlace storage place = eventPlaces[evt.eventPlaceId];
        require(
            place.provider == msg.sender,
            "Only the local provider of the event can update categories"
        );
        require(evt.status == EventStatus.Submitted, "Event must be in submitted state");

        // Gas-efficient quota validation using stored totalCategoryQuota
        if (hasQuota) {
            require(quota > 0, "Quota must be greater than 0");
            require(quota >= category.sold, "Quota cannot be less than tickets already sold");
            require(quota <= place.maxTickets, "Quota exceeds event capacity");

            // Calculate new total: subtract old quota, add new quota
            uint256 newTotalQuota = evt.totalCategoryQuota;
            if (category.hasQuota) {
                newTotalQuota -= category.quota;
            }
            newTotalQuota += quota;
            require(newTotalQuota <= place.maxTickets,
                "Total category quotas exceed event capacity");

            // Update stored total
            evt.totalCategoryQuota = newTotalQuota;
        } else {
            require(category.hasQuota == false, "Cannot change from limited to unlimited quota");
        }

        category.name = name;
        category.discountPercentage = discountPercentage;
        category.quota = quota;
        category.hasQuota = hasQuota;

        emit TicketCategoryUpdated(
            categoryId,
            category.eventId,
            name,
            discountPercentage,
            quota,
            hasQuota
        );
    }

    function getCategory(uint256 categoryId) external view returns (
        string memory name,
        uint256 eventId,
        uint16 discountPercentage,
        uint16 quota,
        bool hasQuota,
        uint16 sold
    ) {
        require(categoryId < categories.length, "Category does not exist");
        TicketCategory storage category = categories[categoryId];
        return (category.name, category.eventId, category.discountPercentage, category.quota, category.hasQuota, category.sold);
    }

    function getCategoriesForEvent(uint256 eventId) external view returns (uint256[] memory) {
        return categoryCounters[eventId];
    }

    function getEventsCount() external view returns (uint256) {
        return events.length;
    }
}

contracts/CyberValleyEventTicket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "./CyberValley.sol";

// TODO: Pad layout after general work finish
contract CyberValleyEventTicket is ERC721, AccessControl {
    using CyberValley for CyberValley.Multihash;

    bytes32 public constant MASTER_ROLE = keccak256("MASTER_ROLE");
    bytes32 public constant STAFF_ROLE = keccak256("STAFF_ROLE");
    bytes32 public constant EVENT_MANAGER_ROLE =
        keccak256("EVENT_MANAGER_ROLE");

    uint256 private lastTokenId;
    mapping(uint256 => CyberValley.Multihash) public ticketsMeta;
    mapping(uint256 => bool) public isRedeemed;

    string public ipfsHost;
    address public eventManagerAddress;

    event TicketMinted(
        uint256 eventId,
        uint256 ticketId,
        uint256 categoryId,
        address owner,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        address referrer,
        uint256 pricePaid
    );

    event TicketRedeemed(uint256 ticketId);

    constructor(
        string memory name,
        string memory symbol,
        address _master,
        string memory _ipfsHost
    ) ERC721(name, symbol) {
        _grantRole(DEFAULT_ADMIN_ROLE, _master);
        _grantRole(MASTER_ROLE, _master);
        _grantRole(STAFF_ROLE, _master);
        ipfsHost = _ipfsHost;
    }

    modifier onlyEventManager() {
        require(
            hasRole(EVENT_MANAGER_ROLE, msg.sender),
            "Must have event manager role"
        );
        _;
    }

    modifier onlyMaster() {
        require(hasRole(MASTER_ROLE, msg.sender), "Must have master role");
        _;
    }

    modifier onlyStaff() {
        require(hasRole(STAFF_ROLE, msg.sender), "Must have staff role");
        _;
    }

    function setEventManagerAddress(address _eventManagerAddress) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(
            _eventManagerAddress != address(0),
            "Event manager address cannot be zero"
        );
        require(
            eventManagerAddress == address(0),
            "Event manager was already saved"
        );
        _grantRole(EVENT_MANAGER_ROLE, _eventManagerAddress);
        eventManagerAddress = _eventManagerAddress;
    }

    function setIpfsHost(string calldata host) public onlyMaster {
        ipfsHost = host;
    }

    function mint(
        address to,
        uint256 eventId,
        uint256 categoryId,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        address referrer,
        uint256 pricePaid
    ) external onlyEventManager {
        lastTokenId += 1;
        _mint(to, lastTokenId);
        ticketsMeta[lastTokenId] = CyberValley.Multihash(
            digest,
            hashFunction,
            size
        );
        emit TicketMinted(eventId, lastTokenId, categoryId, to, digest, hashFunction, size, referrer, pricePaid);
    }

    function mintBatch(
        address to,
        uint256 eventId,
        uint256 categoryId,
        uint256 amount,
        bytes32 digest,
        uint8 hashFunction,
        uint8 size,
        address referrer,
        uint256 pricePaid
    ) external onlyEventManager {
        for (uint256 i = 0; i < amount; i++) {
            lastTokenId += 1;
            _mint(to, lastTokenId);
            ticketsMeta[lastTokenId] = CyberValley.Multihash(
                digest,
                hashFunction,
                size
            );
            emit TicketMinted(eventId, lastTokenId, categoryId, to, digest, hashFunction, size, referrer, pricePaid);
        }
    }

    function ticketMeta(
        uint256 tokenId
    ) external view returns (bytes32 digest, uint8 hashFunction, uint8 size) {
        _requireOwned(tokenId);
        CyberValley.Multihash storage meta = ticketsMeta[tokenId];
        return (meta.digest, meta.hashFunction, meta.size);
    }

    function tokenURI(
        uint256 tokenId
    ) public view virtual override returns (string memory) {
        _requireOwned(tokenId);
        CyberValley.Multihash memory mh = ticketsMeta[tokenId];
        string memory cid = toCID(mh.digest, mh.hashFunction, mh.size);
        return string(abi.encodePacked(ipfsHost, "/", cid));
    }

    function transferFrom(
        address from,
        address to,
        uint256 tokenId
    ) public virtual override {
        require(from == address(0), "Token transfer is disabled");
        super.transferFrom(from, to, tokenId);
    }

    function redeemTicket(uint256 tokenId) external onlyStaff {
        require(!isRedeemed[tokenId], "Token was redeemed already");
        isRedeemed[tokenId] = true;
        emit TicketRedeemed(tokenId);
    }

    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(ERC721, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function toCID(
        bytes32 digest,
        uint8 hashFunction,
        uint8 size
    ) internal pure returns (string memory) {
        if (size == 0) return ""; // Return empty string for size 0

        bytes memory hashBytes = new bytes(32);
        for (uint j = 0; j < 32; j++) {
            hashBytes[j] = digest[j];
        }

        bytes memory multihashBytes = new bytes(2 + hashBytes.length);
        multihashBytes[0] = bytes1(hashFunction);
        multihashBytes[1] = bytes1(size);

        for (uint j = 0; j < hashBytes.length; j++) {
            multihashBytes[j + 2] = hashBytes[j];
        }

        return string(Base58.encode(multihashBytes));
    }
}

// Source: https://github.com/storyicon/base58-solidity/blob/master/contracts/Base58.sol
// It's hard copied cause of requirement to deploy this library if it's imported
// and i it's damn stupid for the given use case
library Base58 {
    bytes constant ALPHABET =
        "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

    function encode(bytes memory data_) internal pure returns (bytes memory) {
        unchecked {
            uint256 size = data_.length;
            uint256 zeroCount;
            while (zeroCount < size && data_[zeroCount] == 0) {
                zeroCount++;
            }
            size = zeroCount + ((size - zeroCount) * 8351) / 6115 + 1;
            bytes memory slot = new bytes(size);
            uint32 carry;
            int256 m;
            int256 high = int256(size) - 1;
            for (uint256 i = 0; i < data_.length; i++) {
                m = int256(size - 1);
                for (carry = uint8(data_[i]); m > high || carry != 0; m--) {
                    carry = carry + 256 * uint8(slot[uint256(m)]);
                    slot[uint256(m)] = bytes1(uint8(carry % 58));
                    carry /= 58;
                }
                high = m;
            }
            uint256 n;
            for (n = zeroCount; n < size && slot[n] == 0; n++) {}
            size = slot.length - (n - zeroCount);
            bytes memory out = new bytes(size);
            for (uint256 i = 0; i < size; i++) {
                uint256 j = i + n - zeroCount;
                out[i] = ALPHABET[uint8(slot[j])];
            }
            return out;
        }
    }
}

contracts/DateOverlapChecker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "@openzeppelin/contracts/utils/math/Math.sol";

contract DateOverlapChecker {
    uint256 initialOffest;
    mapping(uint256 => uint256[]) dateRanges;

    uint256 public constant SECONDS_IN_DAY = 86400;
    uint256 public constant BUCKET_SIZE = 256;

    constructor(uint256 _initialOffest) {
        initialOffest = _initialOffest;
    }

    function checkNoOverlap(
        uint256 id,
        uint256 startDate,
        uint256 endDate
    ) internal view validDateRange(startDate, endDate) returns (bool) {
        uint256[] storage buckets = dateRanges[id];
        // There are no any date ranges stored
        if (buckets.length == 0) {
            return true;
        }
        uint256 startBucketIdx = dateToBucketIdx(startDate);
        // There is no bucket for the given range
        if (startBucketIdx >= buckets.length) {
            return true;
        }
        uint256 endBucketIdx = dateToBucketIdx(endDate);
        uint256 startDaysWithBucketOffset = dateToBucketRelativeDays(
            startDate,
            startBucketIdx
        );
        uint256 endDaysWithBucketOffset = dateToBucketRelativeDays(
            endDate,
            endBucketIdx
        );

        // Easy way, date range inside of single bucket
        if (startBucketIdx == endBucketIdx) {
            return
                daysRangeToMask(
                    startDaysWithBucketOffset,
                    endDaysWithBucketOffset
                ) &
                    buckets[startBucketIdx] ==
                0;
        }

        // Got date range inside of two buckets
        uint256 startMask = daysRangeToMask(startDaysWithBucketOffset, 255);
        // There is no bucket for the second part
        if (endBucketIdx >= buckets.length) {
            return startMask & buckets[startBucketIdx] == 0;
        }
        uint256 endMask = daysRangeToMask(0, endDaysWithBucketOffset);
        return
            startMask & buckets[startBucketIdx] == 0 &&
            endMask & buckets[endBucketIdx] == 0;
    }

    function freeDateRange(
        uint256 id,
        uint256 startDate,
        uint256 endDate
    ) internal validDateRange(startDate, endDate) returns (bool) {
        uint256[] storage buckets = dateRanges[id];
        uint256 startBucketIdx = dateToBucketIdx(startDate);
        uint256 endBucketIdx = dateToBucketIdx(endDate);

        uint256 startDaysWithBucketOffset = dateToBucketRelativeDays(
            startDate,
            startBucketIdx
        );
        uint256 endDaysWithBucketOffset = dateToBucketRelativeDays(
            endDate,
            endBucketIdx
        );

        if (
            startBucketIdx >= buckets.length || endBucketIdx >= buckets.length
        ) {
            return true;
        }

        if (startBucketIdx == endBucketIdx) {
            buckets[startBucketIdx] &= ~daysRangeToMask(
                startDaysWithBucketOffset,
                endDaysWithBucketOffset
            );
            return true;
        }

        buckets[startBucketIdx] &= ~daysRangeToMask(
            startDaysWithBucketOffset,
            255
        );
        buckets[endBucketIdx] &= ~daysRangeToMask(0, endDaysWithBucketOffset);
        return true;
    }

    function allocateDateRange(
        uint256 id,
        uint256 startDate,
        uint256 endDate
    ) internal validDateRange(startDate, endDate) returns (bool) {
        uint256[] storage buckets = dateRanges[id];
        uint256 startBucketIdx = dateToBucketIdx(startDate);
        uint256 endBucketIdx = dateToBucketIdx(endDate);

        uint256 startDaysWithBucketOffset = dateToBucketRelativeDays(
            startDate,
            startBucketIdx
        );
        uint256 endDaysWithBucketOffset = dateToBucketRelativeDays(
            endDate,
            endBucketIdx
        );

        createBucketsIfNeeded(buckets, startBucketIdx);

        if (startBucketIdx == endBucketIdx) {
            buckets[startBucketIdx] |= daysRangeToMask(
                startDaysWithBucketOffset,
                endDaysWithBucketOffset
            );
            return true;
        }
        createBucketsIfNeeded(buckets, endBucketIdx);

        buckets[startBucketIdx] |= daysRangeToMask(
            startDaysWithBucketOffset,
            255
        );
        buckets[endBucketIdx] |= daysRangeToMask(0, endDaysWithBucketOffset);
        return true;
    }

    function dateToBucketIdx(uint256 date) internal view returns (uint256) {
        return (date - initialOffest) / SECONDS_IN_DAY / BUCKET_SIZE;
    }

    function dateToBucketRelativeDays(
        uint256 date,
        uint256 bucketIdx
    ) internal view returns (uint256) {
        return
            (date - initialOffest) / SECONDS_IN_DAY - bucketIdx * BUCKET_SIZE;
    }

    function daysRangeToMask(
        uint256 start,
        uint256 end
    ) internal pure returns (uint256) {
        return ((1 << (end - start + 1)) - 1) << start;
    }

    function createBucketsIfNeeded(
        uint256[] storage buckets,
        uint256 bucketIdx
    ) internal {
        for (
            uint256 idx = Math.max(buckets.length, 1) - 1;
            idx <= bucketIdx;
            idx++
        ) {
            buckets.push(0);
        }
    }

    modifier validDateRange(uint256 startDate, uint256 endDate) {
        require(
            startDate >= initialOffest,
            "Start date should be after initial offset"
        );
        require(
            endDate >= initialOffest,
            "End date should be after initial offset"
        );
        require(
            endDate - startDate < SECONDS_IN_DAY * BUCKET_SIZE,
            "Date range cannot exceed 255 days"
        );
        _;
    }
}

contracts/DynamicRevenueSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./IDynamicRevenueSplitter.sol";

contract DynamicRevenueSplitter is IDynamicRevenueSplitter, AccessControl, ReentrancyGuard {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant PROFILE_MANAGER_ROLE = keccak256("PROFILE_MANAGER_ROLE");

    error EventProfileNotSet(uint256 eventId);
    error ProfileInactive(uint256 profileId);
    error InvalidProfileShares();
    error UsdtTransferFromFailed();
    error UsdtTransferFailed();

    // Fixed recipients (immutable)
    address public immutable cyberiaDAO;      // CyberiaDAO LLC - platform
    address public immutable cvePtPma;        // CVE PT PMA - land owner
    IERC20 public immutable usdt;

    // Fixed shares (constants) - basis points where 10000 = 100%
    uint256 public constant CYBERIA_DAO_SHARE = 1000;      // 10%
    uint256 public constant CVE_PT_PMA_SHARE = 500;        // 5%
    uint256 public constant MAX_PROFILE_MANAGER_BPS = 8500; // 85% max for profile manager
    uint256 public constant BASIS_POINTS = 10000;

    struct RecipientShare {
        address recipient;
        uint16 bps;
    }

    struct Distribution {
        RecipientShare[] recipientShares;
        uint16 totalBps;
        address owner;        // Owner of this profile
        bool isActive;        // Soft delete capability
    }

    Distribution[] internal profiles;
    mapping(uint256 => uint256) public eventProfiles;       // eventId => profileId
    mapping(address => uint256[]) public ownerProfiles;     // owner => profileIds[]

    /**
     * @notice Basis points each profile manager receives from distributions.
     * Applied after fixed bps (CyberiaDAO 10% + CVE PT PMA 5%) and before 
     * profile recipients. Manager cannot add their own address to distribution profiles.
     */
    mapping(address => uint256) public profileManagerBps;   // basis points for each manager

    address public eventManager;

    event DistributionProfileCreated(
        uint256 indexed profileId,
        address indexed owner,
        address[] recipients,
        uint256[] shares
    );
    event DistributionProfileUpdated(uint256 indexed profileId, address[] recipients, uint256[] shares);
    event EventProfileSet(uint256 indexed eventId, uint256 profileId);
    event RevenueDistributed(uint256 amount, uint256 indexed eventId);
    event ProfileOwnershipTransferred(
        uint256 indexed profileId,
        address indexed previousOwner,
        address indexed newOwner
    );
    event ProfileDeactivated(uint256 indexed profileId);

    /**
     * @notice Emitted when a profile manager is granted role with bps share
     * @param account The account granted PROFILE_MANAGER_ROLE
     * @param bps The basis points (0-8500) applied after fixed bps and before profile recipients
     */
    event ProfileManagerGranted(address indexed account, uint256 bps);

    constructor(
        address _usdt,
        address _cyberiaDAO,
        address _cvePtPma,
        address _admin
    ) {
        require(_usdt != address(0), "USDT address cannot be zero");
        require(_cyberiaDAO != address(0), "CyberiaDAO address cannot be zero");
        require(_cvePtPma != address(0), "CVE PT PMA address cannot be zero");
        require(_admin != address(0), "Admin address cannot be zero");

        usdt = IERC20(_usdt);
        cyberiaDAO = _cyberiaDAO;
        cvePtPma = _cvePtPma;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);
    }

    function setEventManager(address _eventManager) external onlyRole(ADMIN_ROLE) {
        require(_eventManager != address(0), "EventManager cannot be zero address");
        eventManager = _eventManager;
    }

    modifier onlyAdminOrEventManager() {
        require(
            hasRole(ADMIN_ROLE, msg.sender) || msg.sender == eventManager,
            "Caller must be admin or EventManager"
        );
        _;
    }

    modifier onlyAdminOrProfileManager() {
        require(
            hasRole(ADMIN_ROLE, msg.sender) || hasRole(PROFILE_MANAGER_ROLE, msg.sender),
            "Caller must have ADMIN_ROLE or PROFILE_MANAGER_ROLE"
        );
        _;
    }

    modifier onlyProfileOwnerOrAdmin(uint256 profileId) {
        require(profileId > 0 && profileId <= profiles.length, "Profile does not exist");
        require(
            profiles[profileId - 1].owner == msg.sender || hasRole(ADMIN_ROLE, msg.sender),
            "Caller must be profile owner or admin"
        );
        _;
    }

    /**
     * @notice Grants PROFILE_MANAGER_ROLE to an account with specified bps share
     * @param account The address to grant the role to
     * @param bps The basis points (0-8500) this account receives from each distribution.
     *           Applied after fixed bps (CyberiaDAO 10% + CVE PT PMA 5%) and before 
     *           profile recipients. Account cannot add themselves to distribution profiles.
     */
    function grantProfileManager(address account, uint256 bps) external onlyAdminOrEventManager {
        require(account != address(0), "Account cannot be zero address");
        require(bps <= MAX_PROFILE_MANAGER_BPS, "Bps must be <= 8500");
        _grantRole(PROFILE_MANAGER_ROLE, account);
        profileManagerBps[account] = bps;
        emit ProfileManagerGranted(account, bps);
    }

    function createDistributionProfile(
        address[] calldata recipients,
        uint256[] calldata shares
    ) external onlyAdminOrProfileManager returns (uint256) {
        (address[] memory fullRecipients, uint16[] memory fullShares) =
            _buildDistribution(msg.sender, recipients, shares);

        uint256 profileId = profiles.length + 1;
        profiles.push();
        Distribution storage profile = profiles[profileId - 1];
        profile.owner = msg.sender;
        profile.isActive = true;
        _setRecipientShares(profile, fullRecipients, fullShares);
        ownerProfiles[msg.sender].push(profileId);

        emit DistributionProfileCreated(
            profileId,
            msg.sender,
            fullRecipients,
            _toUint256Array(fullShares)
        );
        return profileId;
    }

    function updateDistributionProfile(
        uint256 profileId,
        address[] calldata recipients,
        uint256[] calldata shares
    ) external onlyRole(ADMIN_ROLE) {
        Distribution storage profile = profiles[profileId - 1];
        (address[] memory fullRecipients, uint16[] memory fullShares) =
            _buildDistribution(profile.owner, recipients, shares);
        _setRecipientShares(profile, fullRecipients, fullShares);
        emit DistributionProfileUpdated(
            profileId,
            fullRecipients,
            _toUint256Array(fullShares)
        );
    }

    function setEventProfile(uint256 eventId, uint256 profileId) external override {
        require(
            hasRole(ADMIN_ROLE, msg.sender) || msg.sender == eventManager,
            "Caller must be admin or EventManager"
        );
        require(profileId > 0 && profileId <= profiles.length, "Profile does not exist");
        require(profiles[profileId - 1].isActive, "Profile is not active");
        eventProfiles[eventId] = profileId;
        emit EventProfileSet(eventId, profileId);
    }

    function distributeRevenue(uint256 amount, uint256 eventId) external override nonReentrant {
        require(amount > 0, "Amount must be greater than zero");
        uint256 profileId = eventProfiles[eventId];
        if (profileId == 0) {
            revert EventProfileNotSet(eventId);
        }
        if (profileId > profiles.length) {
            revert EventProfileNotSet(eventId);
        }

        Distribution storage profile = profiles[profileId - 1];
        if (!profile.isActive) {
            revert ProfileInactive(profileId);
        }

        // Pull funds from EventManager
        if (!usdt.transferFrom(msg.sender, address(this), amount)) {
            revert UsdtTransferFromFailed();
        }

        uint256 cyberiaDAOAmount = (amount * CYBERIA_DAO_SHARE) / BASIS_POINTS;
        uint256 cvePtPmaAmount = (amount * CVE_PT_PMA_SHARE) / BASIS_POINTS;

        if (cyberiaDAOAmount > 0) {
            _transferUsdt(cyberiaDAO, cyberiaDAOAmount);
        }
        if (cvePtPmaAmount > 0) {
            _transferUsdt(cvePtPma, cvePtPmaAmount);
        }

        _distributeProfileShares(amount, profile);

        // Clear the profile assignment to prevent re-distribution
        eventProfiles[eventId] = 0;

        emit RevenueDistributed(amount, eventId);
    }

    function _distributeProfileShares(uint256 amount, Distribution storage profile) internal {
        uint256 recipientsCount = profile.recipientShares.length;
        if (recipientsCount == 0) {
            revert InvalidProfileShares();
        }
        if (profile.totalBps == 0) {
            revert InvalidProfileShares();
        }

        uint256 profileAmount = (amount * profile.totalBps) / BASIS_POINTS;
        uint256 distributed = 0;
        for (uint256 i = 0; i < recipientsCount; i++) {
            uint256 shareAmount;
            RecipientShare storage recipientShare = profile.recipientShares[i];
            if (i == recipientsCount - 1) {
                // Last recipient gets the remainder to handle rounding
                shareAmount = profileAmount - distributed;
            } else {
                shareAmount = (amount * recipientShare.bps) / BASIS_POINTS;
            }

            if (shareAmount > 0) {
                _transferUsdt(recipientShare.recipient, shareAmount);
                distributed += shareAmount;
            }
        }
    }

    function isProfileOwner(uint256 profileId, address account) external view override returns (bool) {
        require(profileId > 0 && profileId <= profiles.length, "Profile does not exist");
        return profiles[profileId - 1].owner == account;
    }

    function transferProfileOwnership(uint256 profileId, address newOwner) external onlyRole(ADMIN_ROLE) {
        require(profileId > 0 && profileId <= profiles.length, "Profile does not exist");
        require(newOwner != address(0), "New owner cannot be zero address");

        Distribution storage profile = profiles[profileId - 1];
        address previousOwner = profile.owner;
        require(previousOwner != newOwner, "New owner must be different");

        // Remove profileId from previous owner's list
        uint256[] storage prevOwnerProfiles = ownerProfiles[previousOwner];
        for (uint256 i = 0; i < prevOwnerProfiles.length; i++) {
            if (prevOwnerProfiles[i] == profileId) {
                prevOwnerProfiles[i] = prevOwnerProfiles[prevOwnerProfiles.length - 1];
                prevOwnerProfiles.pop();
                break;
            }
        }

        // Add to new owner's list
        profile.owner = newOwner;
        ownerProfiles[newOwner].push(profileId);

        emit ProfileOwnershipTransferred(profileId, previousOwner, newOwner);
    }

    function transferAllProfiles(address from, address to) external override onlyRole(ADMIN_ROLE) {
        require(from != address(0), "From address cannot be zero");
        require(to != address(0), "To address cannot be zero");
        require(from != to, "From and to must be different");

        uint256[] storage fromProfiles = ownerProfiles[from];
        uint256[] storage toProfiles = ownerProfiles[to];

        for (uint256 i = 0; i < fromProfiles.length; i++) {
            uint256 profileId = fromProfiles[i];
            profiles[profileId - 1].owner = to;
            toProfiles.push(profileId);
        }

        // Clear from's list
        delete ownerProfiles[from];
    }

    function deactivateProfile(uint256 profileId) external onlyProfileOwnerOrAdmin(profileId) {
        profiles[profileId - 1].isActive = false;
        emit ProfileDeactivated(profileId);
    }

    function _buildDistribution(
        address owner,
        address[] calldata recipients,
        uint256[] calldata shares
    ) internal view returns (address[] memory fullRecipients, uint16[] memory fullShares) {
        require(recipients.length == shares.length, "Arrays length mismatch");

        uint256 ownerBps = profileManagerBps[owner];
        uint256 expectedInputSharesTotal = BASIS_POINTS - ownerBps - CYBERIA_DAO_SHARE - CVE_PT_PMA_SHARE;
        uint256 totalShares = 0;
        uint256 extraOwnerSlot = ownerBps > 0 ? 1 : 0;

        require(recipients.length + extraOwnerSlot > 0, "Empty distribution");

        fullRecipients = new address[](recipients.length + extraOwnerSlot);
        fullShares = new uint16[](shares.length + extraOwnerSlot);

        for (uint256 i = 0; i < shares.length; i++) {
            require(recipients[i] != address(0), "Zero address recipient");
            require(
                recipients[i] != owner,
                "Profile owner is added automatically to distribution"
            );

            for (uint256 j = i + 1; j < recipients.length; j++) {
                require(recipients[i] != recipients[j], "Duplicate recipient");
            }

            fullRecipients[i] = recipients[i];
            require(shares[i] <= BASIS_POINTS, "Share exceeds bps");
            fullShares[i] = uint16(shares[i]);
            totalShares += shares[i];
        }

        require(totalShares == expectedInputSharesTotal, "Shares must sum to remaining bps");

        if (ownerBps > 0) {
            uint256 ownerIndex = recipients.length;
            fullRecipients[ownerIndex] = owner;
            fullShares[ownerIndex] = uint16(ownerBps);
            totalShares += ownerBps;
        }

        if (totalShares != BASIS_POINTS - CYBERIA_DAO_SHARE - CVE_PT_PMA_SHARE) {
            revert InvalidProfileShares();
        }
    }

    function _setRecipientShares(
        Distribution storage profile,
        address[] memory recipients,
        uint16[] memory shares
    ) internal {
        delete profile.recipientShares;
        uint256 totalBps = 0;
        for (uint256 i = 0; i < recipients.length; i++) {
            profile.recipientShares.push(
                RecipientShare({recipient: recipients[i], bps: shares[i]})
            );
            totalBps += shares[i];
        }
        if (totalBps != BASIS_POINTS - CYBERIA_DAO_SHARE - CVE_PT_PMA_SHARE) {
            revert InvalidProfileShares();
        }
        profile.totalBps = uint16(totalBps);
    }

    function _toUint256Array(uint16[] memory values) internal pure returns (uint256[] memory) {
        uint256[] memory out = new uint256[](values.length);
        for (uint256 i = 0; i < values.length; i++) {
            out[i] = values[i];
        }
        return out;
    }

    function _transferUsdt(address to, uint256 amount) internal {
        if (!usdt.transfer(to, amount)) {
            revert UsdtTransferFailed();
        }
    }
}

